	public virtual float GetElementalDamageModifier(ElementType damageType)
	{
		if (damageType == ElementType.Neutral)
		{
			return 1f;
		}
		eleDmgModVal = 0;
		if (entityScript != null)
		{
			tempEleType = entityScript.element;
			if (tempEleType == damageType)
			{
				eleDmgModVal = -2;
			}
			else if (eleWheelDict.ContainsKey(tempEleType) && eleWheelDict[tempEleType] == damageType)
			{
				eleDmgModVal = 2;
			}
			else if (eleWheelDict.ContainsKey(damageType) && eleWheelDict[damageType] == tempEleType)
			{
				eleDmgModVal = -1;
			}
		}
		return 1f + (float)eleDmgModVal * baseEleBoostValue;
	}

