	public void ExecuteAttack(Collider2D col)
	{
		targetHealth = col.gameObject.GetComponent<Health>() ?? col.transform.parent.gameObject.GetComponent<Health>();
		if (targetHealth == null)
		{
			return;
		}
		onHitAtkInfo = new AttackInfo(atkInfo);
		onHitAtkInfo.time = Time.time;
		onHitAtkInfo.targetObjID = col.gameObject.GetInstanceID();
		onHitAtkInfo.attackerPosition = transform.position;
		onHitAtkInfo.targetPosition = col.transform.position;
		if (targetHealth.passThroughAttack)
		{
			targetHealth.TakeDamage(onHitAtkInfo, onHitAtkInfo.entity, critPreCalculated: true);
			return;
		}
		if (Random.value < targetHealth.evadeStat.CurrentValue)
		{
			EvadeAttack(onHitAtkInfo, col);
			return;
		}
		if (!damageModifierApplied && onHitAtkInfo.damage > 0)
		{
			damageModifierApplied = true;
			onHitAtkInfo.damage = Mathf.Max(1, Mathf.FloorToInt((float)onHitAtkInfo.damage * damageModifier));
		}
		if (damageOverride > -1)
		{
			onHitAtkInfo.damage = damageOverride;
		}
		if (damageOverride == 0)
		{
			onHitAtkInfo.canHitStun = false;
			onHitAtkInfo.showDamageEffect = false;
			onHitAtkInfo.showDamageNumber = false;
		}
		onHitAtkInfo.attackingVector = (col.transform.position - transform.position).normalized;
		onHitAtkInfo.knockbackVector = GetKnockbackVector(col.transform.position, transform.position, onHitAtkInfo.knockbackMultiplier, onHitAtkInfo.knockbackOverwrite, attackerPosOffet);
		if (onHitAtkInfo.shakeCamera)
		{
			CameraController.ShakeCamera(Mathf.Min((float)onHitAtkInfo.damage * CamShakeMultiplier.CurrentValue, 2f));
		}
		AnnounceCollisionEvent(col, targetHealth.entityScript);
		if (!targetHealth.invulnerable && Random.value < onHitAtkInfo.critHitChance)
		{
			if (targetHealth.evadeCrit)
			{
				EvadeAttack(onHitAtkInfo, col);
				return;
			}
			if (globalCritEventHandlers != null)
			{
				globalCritEventHandlers(onHitAtkInfo, onHitAtkInfo.entity, targetHealth.entityScript);
			}
			onHitAtkInfo.isCritical = true;
			onHitAtkInfo.damage = Mathf.FloorToInt(onHitAtkInfo.critDmgModifier * (float)onHitAtkInfo.damage);
		}
		if (onHitAtkInfo.isUltimate)
		{
			onHitAtkInfo.damage = Mathf.FloorToInt(onHitAtkInfo.odDmgModifier * (float)onHitAtkInfo.damage);
		}
		if (onHitAtkInfo.isDamageOverride)
		{
			onHitAtkInfo.damage = atkInfo.damage;
		}
		targetHealth.TakeDamage(onHitAtkInfo, onHitAtkInfo.entity, critPreCalculated: true);
		UpdateAttackHistory(onHitAtkInfo.attackInfoKey, onHitAtkInfo);
	}

